#!/bin/bash
# Proceed-protocol baselines (PatchTST, ETTm1, L=512) with prediction dumps for pooling as external experts.
# Generated by make_pre9.py from the released OnlineTSF PatchTST scripts.
W=/kaggle/working
export SEED_OFFSET=1
chain () {
  H=$1; G=$2; MID=$3; BTL=$4; LR=$5; OLR=$6
  COMMON="--dataset ETTm1 --border_type online --model PatchTST --seq_len 512 --pred_len $H --itr 1 --gpu $G"
  python -u run.py $COMMON --pin_gpu True --reduce_bs False --save_opt --batch_size 128 --train_epochs 100 --pct 0.4 \
      --patience 10 --learning_rate 0.0001 > $W/baseline_logs/pretrain_ETTm1_H$H.log 2>&1
  DUMP_PREDS=$W/preds/GD__ETTm1__L512__H$H python -u run.py $COMMON --online_method Online --online_learning_rate 0.0000003 \
      --pin_gpu True --reduce_bs False --save_opt --only_test > $W/baseline_logs/gd_ETTm1_H$H.log 2>&1
  DUMP_PREDS=$W/preds/Proceed__ETTm1__L512__H$H python -u run.py $COMMON --batch_size 16 --tune_mode down_up \
      --concept_dim $MID --val_online_lr --diff_online_lr --pretrain --wo_clip --save_opt --online_method Proceed \
      --bottleneck_dim $BTL --online_learning_rate $OLR --learning_rate $LR --lradj type3 > $W/baseline_logs/proceed_ETTm1_H$H.log 2>&1
  grep -h "^mse:" $W/baseline_logs/*_ETTm1_H$H.log
}
chain 24 0 250 48 0.001 0.00001 &
chain 48 1 250 48 0.001 0.00001 &
wait
chain 96 0 150 48 0.001 0.00001
ls -la $W/preds
